insert into public.chemicals (id, name, epa_number, category, repellency, mix_ratios, notes) values
  ('chem-taurus-sc', 'Taurus SC', '53883-279', 'General Pest - Exterior', 'non-repellent', '[{"context":"Standard mix (backpack sprayer)","ratio":"0.8 fl oz / 1 gal water"},{"context":"Exterior perimeter - March/April rotation","ratio":"0.8 fl oz / 1 gal water"},{"context":"Exterior perimeter - July/August rotation","ratio":"0.8 fl oz / 1 gal water"}]'::jsonb, 'Fipronil non-repellent. Ants cannot detect it, so they carry it back to the colony - excellent on ants, not as effective on other pests. Label restrictions you must follow: maximum 2 applications per year, and no application further than 1 ft from the structure. Apply with a dedicated non-repellent backpack sprayer to prevent contamination with repellent products. Listed on the technician cheat sheet alongside the termiticide products; the Single Family procedure uses it as the exterior perimeter non-repellent in the seasonal rotation. The source procedure marks the Taurus SC application standard as pending internal discussion.'),
  ('chem-termidor-he', 'Termidor HE', '7969-329', 'Termite', 'non-repellent', '[{"context":"Standard mix","ratio":"1.6 fl oz / 1 gal water"}]'::jsonb, 'Termiticide. High-efficiency fipronil formulation for termite trenching and treatment. Follow label and state regulations for volume per linear foot.'),
  ('chem-sentricon-recruit-hd', 'Sentricon Recruit HD', '62719-608', 'Termite', 'n/a', '[{"context":"Station placement (not a mixed product)","ratio":"1 station / 10 ft"}]'::jsonb, 'Termite baiting system. Placement rate, not a dilution - install one station every 10 ft around the structure.'),
  ('chem-suspend-sc', 'Suspend SC', NULL, 'General Pest - Exterior', 'repellent', '[{"context":"Exterior perimeter application","ratio":"0.75 fl oz / 1 gal water"}]'::jsonb, 'Deltamethrin repellent residual. Do not apply over a non-repellent treatment or a granular bait - it will contaminate them.'),
  ('chem-suspend-polyzone', 'Suspend Polyzone', NULL, 'General Pest - Exterior', 'repellent', '[{"context":"Standard mix (cheat sheet general list)","ratio":"1 fl oz / 1 gal water"},{"context":"Exterior perimeter application","ratio":"0.75 fl oz / 1 gal water"}]'::jsonb, 'DISCREPANCY: the technician cheat sheet lists Suspend Polyzone at 1 fl oz per gallon in the general product list and at 0.75 fl oz per gallon under Exterior Perimeter Application. Both are recorded here - confirm which rate applies to your job with your Service Manager. The source also marks this product with an asterisk but gives no matching footnote. Repellent - do not apply over non-repellents or baits.'),
  ('chem-demand-cs', 'Demand CS', NULL, 'General Pest - Exterior', 'repellent', '[{"context":"Exterior perimeter application","ratio":"0.4 fl oz / 1 gal water"}]'::jsonb, 'Lambda-cyhalothrin capsule suspension, repellent. Named in the Single Family procedure as the example of what NOT to spray over a non-repellent ant treatment.'),
  ('chem-onslaught-fastcap', 'Onslaught FastCap', NULL, 'General Pest - Exterior', 'repellent', '[{"context":"Standard mix","ratio":"1 fl oz / 1 gal water"},{"context":"Exterior perimeter - May/June rotation","ratio":"1.0 fl oz / 1 gal water"},{"context":"Exterior perimeter - September/October rotation","ratio":"1.0 fl oz / 1 gal water"}]'::jsonb, 'Long-lasting pyrethroid residual spray. May be substituted for stubborn pests on exterior treatments. Repellent - keep off areas treated with Niban or a non-repellent.'),
  ('chem-pro-flex', 'Pro-Flex', NULL, 'IGR', 'n/a', '[{"context":"Standard mix","ratio":"1 fl oz / 1 gal water"}]'::jsonb, 'Listed on the technician cheat sheet at 1 fl oz per gallon with no application context given, grouped next to Tekko Pro. Confirm target pest, site, and placement with your Service Manager before use.'),
  ('chem-tekko-pro', 'Tekko Pro', NULL, 'IGR', 'n/a', '[{"context":"Standard mix","ratio":"1 fl oz / 1 gal water"}]'::jsonb, 'Insect growth regulator. Breaks the reproductive cycle rather than killing adults, so pair it with a residual or bait. No repellency concern.'),
  ('chem-fipronil-plus-c', 'Fipronil Plus-C', NULL, 'General Pest - Exterior', 'non-repellent', '[{"context":"Service calls for ants / roaches - exterior spot treatment only","ratio":"0.75 fl oz / 1 gal water"}]'::jsonb, 'Exterior SPOT treatment only - not a full perimeter product. Non-repellent, so use a dedicated non-repellent sprayer and do not spray a repellent over it.'),
  ('chem-gentrol-igr', 'Gentrol IGR', NULL, 'IGR', 'n/a', '[{"context":"Interior general pest - Accusprayer (16 fl oz)","ratio":"0.125 fl oz / 16 fl oz water"},{"context":"Interior general pest - backpack power sprayer (1 gal)","ratio":"1 fl oz / 1 gal water"}]'::jsonb, 'Hydroprene growth regulator for interior work. 16 fl oz mixes are solely for the Accusprayer; 1 gallon mixes are primarily for the backpack power sprayer. Pair with Alpine WSG for German roaches.'),
  ('chem-alpine-wsg', 'Alpine WSG', NULL, 'General Pest - Interior', 'non-repellent', '[{"context":"Interior general pest - Accusprayer (16 fl oz)","ratio":"2.5 g / 16 fl oz water"},{"context":"Interior general pest - backpack power sprayer (1 gal)","ratio":"20 g / 1 gal water"},{"context":"Cleanout for active infestation (1 gal)","ratio":"10 g / 1 gal water"}]'::jsonb, 'DISCREPANCY: the cheat sheet lists Alpine WSG at 20 g per gallon under Interior General Pest Control and again at 10 g per gallon in the active-infestation cleanout section. Both rates are recorded here - confirm which applies with your Service Manager before mixing. Dinotefuran, non-repellent: roaches walk through treated areas unknowingly and transfer lethal doses back to the harborage. For German roaches, Alpine WSG plus Gentrol IGR is the preferred pure non-repellent approach. The source also marks this product with an asterisk but gives no matching footnote.'),
  ('chem-ridesco-wg', 'Ridesco WG', NULL, 'Cleanout / Infestation', 'non-repellent', '[{"context":"Cleanout for active infestation - Accusprayer (16 fl oz)","ratio":"2.5 g / 16 fl oz water"},{"context":"Cleanout for active infestation - backpack power sprayer (1 gal)","ratio":"20 g / 1 gal water"}]'::jsonb, 'Used for cleanouts, initial services, and callbacks on active ant and roach infestations, interior and exterior. Per the cheat sheet, non-repellents are used on the outside exclusively and Ridesco WG is the non-repellent for that. Active infestation work must be performed by a certified technician.'),
  ('chem-barricor', 'Barricor', NULL, 'General Pest - Exterior', 'repellent', '[{"context":"Exterior perimeter - January/February rotation","ratio":"0.5 fl oz / 1 gal water"},{"context":"Exterior perimeter - November/December rotation","ratio":"0.5 fl oz / 1 gal water"}]'::jsonb, 'Long-lasting pyrethroid residual spray and the standard for exterior perimeter treatments. Repellent - do not apply over Niban granular bait or a non-repellent treatment.'),
  ('chem-niban', 'Niban', NULL, 'Granular Bait', 'n/a', '[{"context":"Perimeter conducive areas (per home)","ratio":"about 0.5 lb per home"},{"context":"Treated band width","ratio":"approximately 4 ft wide in conducive areas"}]'::jsonb, 'Long-lasting granular bait for conducive areas: shrub beds along the home, AC drip lines, wet areas, near trash cans. Slow to work but lasts 2-3 months and works on a wide variety of pests. Apply only where Barricor, Onslaught FastCap, or Taurus SC was NOT sprayed, to prevent bait contamination.'),
  ('chem-fasttrac-blox', 'Fasttrac Blox', NULL, 'Rodent', 'n/a', '[{"context":"Initial station loading","ratio":"4 blox per station"},{"context":"Maintenance - light activity","ratio":"minimum 2 blox per station"},{"context":"Bait completely consumed / heavy activity","ratio":"up to 8 blox per station"}]'::jsonb, 'Standard rodent bait. Works after only one feeding; rodents die in 5-7 days. Use only inside child and pet resistant Protecta Evo stations. Replace bait if it is consumed, moldy, or otherwise deteriorated. Never leave bait unsecured - replace a broken or unsecured station immediately.')
insert into public.procedures (id, slug, title, summary, category, frequency, sort, updated_at) values
  ('proc-residential-service', 'residential-pest-plus-rodent-service', 'Residential Pest Control Plus Rodent Service Process', 'The six-step field workflow for a residential pest and rodent visit, from route verification through closing the job in the system. Follow this on every scheduled residential service.', 'Service Workflow', 'Every scheduled visit', 1, '2026-07-20'),
  ('proc-single-family', 'single-family-pest-prevention', 'Single Family Home Pest Prevention Procedure', 'The master exterior-based prevention procedure for single family homes: program coverage, initial inspection, preventative perimeter treatment, rodent stations for Plus customers, and the seasonal chemical rotation.', 'Service Procedures', '4x per year', 2, '2026-07-20')
