  ('step-sf-094', 'sec-sf-materials', 'Ladder, if the attic needs to be inspected.', 'step', 1, 12, '[]'::jsonb),
  ('step-sf-095', 'sec-sf-materials', 'Backpack sprayers - one dedicated repellent, one dedicated non-repellent.', 'step', 1, 13, '[]'::jsonb),
  ('step-sf-096', 'sec-sf-materials', 'B&G sprayers - one dedicated repellent, one dedicated non-repellent.', 'step', 1, 14, '[]'::jsonb),
  ('step-sf-097', 'sec-sf-materials', 'Respirator, if needed in an attic or crawlspace.', 'step', 1, 15, '[]'::jsonb),
  ('step-sf-098', 'sec-sf-materials', 'The source procedure flags the equipment list as pending internal discussion. Confirm the current standard truck load-out with your Service Manager.', 'tip', 0, 16, '[]'::jsonb),
  ('step-sf-099', 'sec-sf-education', 'Remember to educate the customer. Remind them that:', 'step', 0, 1, '[]'::jsonb),
  ('step-sf-100', 'sec-sf-education', 'Most pests come from the outside. We can stop most pests with only exterior treatments, so there is no need to treat the interior every time.', 'step', 1, 2, '[]'::jsonb),
  ('step-sf-101', 'sec-sf-education', 'Sticky monitors and baits are preferred if inside treatments are required.', 'step', 1, 3, '[]'::jsonb),
